  "content.84fee1b908": "Crosswind Blades",
  "content.21f48f0714": "Paired crescent bıçakları dışarı çıkıyor, sonra bir eğri dönüş yolu boyunca geri dilim.",
  "content.bceb0fd05d": "Tesla Bobinleri",
  "content.20e9db560e": "Seni geride bırakıyorlar, yakındaki fosları zap ve önceki zile doğru çizgiyi ayırdılar.",
  "content.3fa4624af4": "Füze Sürüsü",
  "content.d5a30861d8": "Küçük güdümlü füzeleri sürekli bir yelpaze halinde fırlatır. Küçük patlamalar kalabalığı ezer.",
  "content.33308c454a": "Prizma Parçaları",
  "content.7b8ce4b3a3": "Düşmanlar arasında Crystals ricochet. Her biri ilk vuruşunda iki küçük kristale bölünür.",
  "content.6ae4da1570": "Işık Kırbacı",
  "content.dda58a2099": "LEFT CLICK: Geniş bir yay boyunca esnek bir kiriş süpürüyor.Her salak bir kez bir foe vurur.",
  "content.d20d4a8f64": "Cep Nöbetçisi",
  "content.5191e9018c": "Hırs K: Yollarda bir tane dağıtın ve düşmanları vur; en eskileri başka bir şekilde yerine getirir.",
  "content.b2ecb120df": "Cam Gale",
  "content.1519201745": "Crosswind Blades + Prism Shards. Crescent bıçakları kalabalık aracılığıyla kristal flaşlara patladı.",
  "content.1ded80863d": "Hornet Grid",
  "content.5085777882": "Tesla Rolls + Swarm Füzeleri. Bir elektrik füze bataryası: mikro izinli patlamalar, izinizi koruyorken yakındaki düşmanların üzerinden yıldırım atlıyor.",
  "content.7bd71968dd": "Riposte Hücre",
