  "content.dd10e5feed": "Ayaklanma Ovation",
  "content.1b913d3b3f": "Sweep geniş bir yay boyunca esnek bir kiriş. Her salak bir kez foe vurur.",
  "content.a0fe8c20b1": "Deploy a sentry at the cursor. it track and shoots düşmanları; diğerini en eski yerine koyar.",
  "content.672418ed7d": "Parry: ⟪1⟫s için +⟪0⟫ hasarı elde eder. Multipliers'den önce koyun.",
  "content.9ec4a01350": "Mükemmel dash: Orbit ve Trail, ⟪1⟫'ler için +⟪0⟫ hasar alır.",
  "content.f6d86f700c": "Nihainizi kullanın: ⟪1⟫'ler için% ⟪0⟫ hasar.",
  "content.3347d5257c": "Bir combo'da nakit: ⟪1⟫'ler için +⟪0⟫ hasarı elde edin. altın bonus yok.",
  "content.73023179eb": "Bir rewind tamamlandıktan sonra: ⟪1⟫ için% ⟪0⟫ hasar.",
  "content.9f02fc66b3": "Mekadan sağ çık: fırlatma patlaması dahil ⟪1⟫sn boyunca +⟪0⟫% hasar.",
  "content.c21d055973": "Bir göğüs açın: ⟪0⟫m Şok nova ⟪1⟫ zarar veriyor.",
  "content.4796d804bf": "Alev Çizmelerinin ateşindeyken Ateş ve İz vuruşları +⟪0⟫% hasar verir.",
  "content.1c57742cae": "⟪0⟫m'de kapak: Orbit ve Alan +⟪1⟫% hasar alır.",
  "content.b1bbcf2021": "⟪0⟫m ve ötesinde Buz ve Zincir vuruşları +⟪1⟫% hasar verir.",
  "content.a58a60981e": "Her hit +⟪0⟫ hasar. Max life x⟪1⟫. multipliers önce koyun.",
  "content.5e37395e25": "Her bir hit ⟪0⟫ hasarını kaybeder, sonra x⟪1⟫. Güçlü vuruşlar kazanır; sipariş önemlidir.",
  "content.352a455638": "Yaktığın düşmana karşı arkadaşların +⟪0⟫% kritik şansı kazanır (takım sınırı +⟪1⟫%).",
  "content.0836247367": "⟪0⟫m'teki diğer müttefikler tüm silahları ⟪1⟫% daha hızlı şarj eder (team cap +⟪2⟫% hız).",
  "content.e76459c2b5": "⟪0⟫m içindeki bir arkadaşın savuşturursa ⟪1⟫m'lik Şok novasıyla ⟪2⟫ hasar verirsin. Bekleme: ⟪3⟫sn.",
  "content.87006ad396": "Öldürmelerden gerçekten yenilediğin canın ⟪0⟫%'ini ⟪1⟫m içindeki her arkadaşınla paylaş (sınır ⟪2⟫%).",
  "content.5cb95a9e84": "⟪0⟫m içindeki bir arkadaşın kusursuz kaçış yaparsa ⟪1⟫sn dokunulmazlık kazanırsın (en fazla ⟪2⟫sn). Bekleme: ⟪3⟫sn.",
  "content.07d6955765": "Bir müttefik ⟪0⟫m'de nihai bir şekilde kullanır: hitleriniz ⟪2⟫ için% ⟪1⟫ hasar alır.",
