  "text.napalm_ac4b31": "Napalm",
  "text.combo_blast_a_burning_enemy_bd5453": "COMBO: YANIYOR BİR DÜŞMAN",
  "text.an_explosion_that_catches_a_burning_enemy_spread_2f28fe": "Yanan bir düşmanı yakalayan patlama, alanındaki herkese ateş yayar.",
