  "text.relic_62a15e": "YADİGÂR",
  "text.evolution_57341e": "⟪0⟫ EVRİM",
  "text.max_a05aea": "MAX ⟪0⟫ + ⟪1⟫",
  "text.follow_the_moving_dirt_mound_only_explosions_rea_d78566": "Hareket eden toprak yığınını takip et. Yeraltındayken yalnızca patlamalar ona ulaşır. Kırmızı halkadan çık, sonra yüzeye çıktığında vur.",
  "text.an_armoured_dirt_digger_explosions_still_reach_i_24d97e": "Zırhlı bir kazıcı. Patlamalar yeraltına hâlâ ulaşır; saldırı fırsatı için halkanın dışında bekle.",
  "text.an_armoured_mirror_bot_with_the_same_readable_sc_a10396": "Aynı okunabilir tarama ile bir zırhlı Ayna Bot, bonus paralarını iddia etmek için kopya saldırısını parçaladı.",
  "text.a_big_digger_with_a_wider_eruption_its_longer_ri_f0ce60": "Daha geniş bir alana saldıran dev kazıcı. Uzun halka uyarısı kaçman için zaman tanır; patlayıcılar toprağın altına ulaşır.",
  "text.scans_your_left_click_weapon_then_copies_a_weake_09264c": "Sol tıklama silahını tarayın, sonra daha zayıf bir mor versiyonunu kopyalayın. bonus paraları için kopyalarken öldürün.",
  "text.copies_for_longer_and_keeps_farther_away_the_sca_eea86f": "Daha uzun süre Copies ve uzak tutar. Saldırıdan önce tarama hattı kilitleri; kenar yolları.",
  "text.screeches_before_a_wall_of_swarmers_splits_the_a_5886e0": "Bir swarmers duvarının bir duvarından önce bıçakları ayırın ve bir geri çekilmesini kovalar.",
  "text.a_fragile_cluster_that_hatches_four_swarmers_aft_adbb89": "Altı saniye sonra dört swarmer'i kaplayan kırılgan bir küme. Önce yok!",
  "text.holds_the_queen_s_wall_for_twelve_seconds_then_j_2f703d": "Kraliçe'nin duvarını on iki saniye boyunca tut, sonra kovanlara katılın. hat üzerinden bir boşluk vur.",
  "text.comes_in_clouds_and_rings_keep_moving_and_let_ar_696216": "Bulutlarda ve halkalarda gelin. Hareket etmeye devam edin ve bölgeye silahların işi yapmasına izin verin.",
  "text.flashes_red_then_lunges_sidestep_the_lunge_and_i_ff7780": "Flashes kırmızı, sonra akciğerler. Silaha binin ve açık.",
  "text.fast_and_fragile_pierce_and_chain_weapons_clean__db8a3b": "Hızlı ve kırılgan. Pierce ve zincir silahları paketleri temizliyor.",
  "text.keeps_its_distance_and_fires_a_fan_strafe_across_fcd7c5": "Mesafelerini tut ve bir fanı ateşler. fana karşı Strafe, ondan uzak değil.",
  "text.spins_out_a_double_spiral_walk_with_the_gaps_as__21410b": "Çift bir spiral ortaya çıkıyor. Onlar dönüştüğü gibi boşluklarla yürüyün.",
  "text.three_quick_fans_in_a_row_dash_through_after_the_d70eb7": "Üç hızlı fanlar bir satırda. Dash üçüncüden sonra.",
  "text.its_red_line_shows_the_shot_step_off_the_line_be_b5eac6": "Kırmızı çizgi, atışı gösterir. kilitleri kilitlemeden önce çizgiyi kapatın.",
  "text.lines_up_a_charge_you_can_see_on_the_ground_step_9fb66f": "Yerde görebileceğiniz bir şarj yukarı doğru, sonra cezalandırmak.",
  "text.big_slow_and_tough_kite_it_while_you_deal_with_t_81c8c9": "Big, yavaş ve zor. Kite, geri kalanıyla uğraşırken.",
  "text.its_fuse_ticks_faster_before_it_blows_back_off_o_69aede": "Çiçeği havaya uçurmadan önce daha hızlı yuvarlanır veya hızlı bir şekilde öldürür.",
  "text.splits_into_jellets_when_it_pops_area_damage_han_4e2406": "Yalanlar Jellets'e pops. Alan hasarı solun üstesinden gelir.",
  "text.small_jelly_pieces_weak_on_their_own_ea1dfc": "Küçük Jelly parçaları. Kendileri üzerine eğilin.",
  "text.its_shield_soaks_hits_from_the_front_and_covers__241479": "Onun kalkan soaks cepheden vurur ve arkasını gizleyenleri kapsar. Yavaş yavaş döner: tarafını yuvarlan.",
  "text.hangs_back_and_heals_everything_near_it_in_a_gre_b5a071": "Geri asır ve yeşil bir pulda her şeyi iyileştirir. Önce onu öldürün.",
  "text.crouches_then_hops_over_cover_onto_the_ring_it_m_8be58e": "Crouches, o zaman yüzüğün üstüne kapağını umuyor. ringin üzerinden adım at.",
  "text.lobs_shells_from_far_away_each_one_marks_a_red_c_0eed8b": "Lobs uzaklardan kabuklar. Her biri topraklarından önce kırmızı bir daire işaret ediyor.",
  "text.rare_and_shiny_runs_away_and_vanishes_after_a_fe_ee55d0": "Nadir ve parlak. Birkaç saniye sonra kaçar ve vanishes! bir Bonus için onu yakalayın!",
  "text.a_pylon_that_keeps_hatching_swarmers_take_it_out_a463e8": "Swarmers'i ele geçirmeye devam eden bir pylon. Bunu erken çıkarın.",
  "text.rings_of_bullets_summons_and_a_jump_slam_you_can_d79675": "Mermi halkaları, çağırdığı yardımcılar ve önceden belli olan sıçrama saldırısı. Kırmızı çemberin dışında kal.",
  "text.charges_three_times_in_a_row_then_spirals_watch__97dd83": "Bir satırda üç kez şarjlar, sonra spiraller. şarj hatları izleyin.",
  "text.flies_at_range_fires_fans_and_marks_ground_strik_849266": "Çeşitli, yangınlar fanlar ve zemin grevleri işaret eder. Kırmızı bölgeler arasında hareket ettirin.",
  "text.circles_you_then_dives_along_the_orange_line_and_61bb99": "Çemberler sizi, sonra portakal hattı boyunca atlar ve arkadaşları bir sütunda takip eder.",
  "text.swims_under_the_sand_where_nothing_can_hit_it_wa_9f4658": "Hiçbir şeyin vuramayacağı kumun altındaki yüzeler: fin için izleyin. Kırmızı yüzüğün dışına patladı, sonra maruz kaldı.",
  "text.rolls_in_wide_arcs_and_grows_as_it_rolls_it_can__5fcd18": "Geniş yaylarda Rolls ve yuvarlandığı gibi büyür. zar zor bir şekilde dönebilir, bu yüzden yan adım; büyükler duvarlarda ve üzerinizde parçalanır.",
  "text.leaves_burning_puddles_behind_it_and_swells_up_t_07f5e8": "Bunun arkasında puddles yakmak ve büyük bir tane dökmek için ayağa kalk. Zemini boyamadan önce onu öldür.",
  "text.rewinds_its_path_lights_up_then_marches_straight_fa5ceb": "Rewinds (yol ışıkları yukarı), sonra doğrudan takımla sıraya yürüdü. Rüzgar aşağı, ekstra hasar alır.",
  "text.keeps_its_distance_and_blows_a_cone_of_wind_that_1d3a90": "Mesafelerini tut ve etrafınızdaki rüzgarın bir kısmını havaya uçurur. pale cone veya dash'in dışına çıkarın.",
