  "text.once_tiny_garden_helpers_these_machines_now_mist_1558e4": "Küçük bahçe yardımcıları bir kez, bu makineler şimdi bir weed için her boot yanlış.",
  "text.the_islands_oldest_delivery_bot_still_insists_th_70852e": "Adaların en eski teslimat botu hala her parselin kişisel olarak geldiğini ısrar ediyor.",
  "text.a_courier_with_no_address_left_to_deliver_to_its_14143a": "Hiçbir adrese teslim edilmek için ayrılan bir kurye. rotası nerede durduğunuz yerde sona erer.",
  "text.a_retired_fireworks_launcher_still_rehearsing_fo_c984e2": "Emekli bir yangın işi başlatıyor, hala hiç gelmemiş bir festival için prova yapıyor.",
