  "text.three_short_knocks_were_once_the_repair_crew_s_s_bcacff": "Üç kısa mermi bir zamanlar tamir mürettebatının gizli selamı oldu. Bu bot hatırlıyor.",
  "text.the_watchtower_sentry_can_count_the_scratches_on_c73dcc": "Gönderilen saat, adadaki kaskınızın üzerine çizebilir.",
  "text.a_quarry_hauler_with_excellent_acceleration_and__1029b6": "Mükemmel bir ivme ile bir kurry hauler ve kesinlikle fren yok.",
  "text.under_that_heavy_shell_is_a_remarkably_small_bat_5d4742": "Bu ağır kabuk altında oldukça küçük bir batarya ve büyük bir görev duygusu.",
  "text.the_warning_sticker_fell_off_the_warning_noise_f_02ac0e": "Uyarı etiketi düştü. Uyarı gürültüsü, neyse ki, hala çalışır.",
  "text.the_recycling_plant_called_this_self_repair_the__92b56d": "Bu kendini terk eden geri dönüşüm bitkisi, alan ekibi onu ekstra kağıt işi olarak adlandırıyor.",
  "text.a_little_piece_of_a_much_bigger_problem_determin_9984a9": "Çok daha büyük bir problemin küçük bir parçası, kendi yolunu yapmaya karar verdi.",
  "text.the_factory_foreman_never_received_the_shutdown__614054": "Fabrika foreman asla kapatma emri almadı. Üretim devam ediyor.",
  "text.built_to_shelter_workers_from_falling_rock_it_st_30a8cc": "Kayalığa düşen işçilere sığınmak için inşa edilmiş; yine de herkesi ilk başta yapıyor.",
  "text.its_medical_license_expired_with_the_old_network_4e514c": "Tıbbi lisansı eski ağla sona erdi. Yatak şekli coşkulu kalır.",
  "text.the_island_drains_needed_a_maintenance_robot_tha_25ca9a": "Ada drenajları atabilecek bir bakım robotuna ihtiyaç duyuyordu. Kimse bir iniş noktası belirtmedi.",
  "text.an_irrigation_system_that_found_the_wrong_kind_o_7b0a51": "Tedarik dökmesinde yanlış bir tür kanister bulunan bir sulama sistemi.",
  "text.every_loose_bolt_on_the_islands_eventually_ends__83950b": "Adalarda her gevşek Bolt sonunda bu koleksiyoncunun ceplerinde biter.",
  "text.the_first_bopper_promoted_itself_when_the_human__947489": "İlk Bopper kendini insan denetçilerinin ayrıldığında teşvik etti. taç bir antendir.",
  "text.the_excavation_project_stopped_at_bedrock_rex_to_8bf630": "kazı projesi yataktarock'ta durdu. Rex bunu kişisel olarak aldı.",
  "text.from_her_aerial_command_post_she_conducts_the_fa_f2d7d4": "Onun hava komuta postasından, fabrikayı bir pirinç grubu gibi yapıyor.",
  "text.the_central_relay_has_waited_through_a_thousand__3619a8": "Merkezi röle binlerce sessiz günbatımı bekliyor. Şimdi her ada bir kez çağırıyor.",
  "text.a_junior_supervisor_practising_a_royal_entrance__43e53e": "Genç bir denetçi gerçek promosyondan önce bir kraliyet girişi uyguluyor.",
  "text.a_prototype_digger_that_already_dreams_of_moving_bf3a30": "Zaten dağları hareket eden bir prototip digger.",
  "text.her_first_command_assignment_is_this_island_she__03b2ed": "İlk komut ataması bu adadır. İyi bir izlenim yapmak niyetindedir.",
  "text.a_portable_workshop_unfortunately_its_only_repai_004521": "Bir portatif atölye. Ne yazık ki, tek onarım planı daha fazla sorun yaratmaktır.",
  "text.the_network_sends_this_collector_when_an_overdue_f55499": "Ağ bu koleksiyoncuyu aşırı çalışma düzeni bir efsane haline geldiğinde gönderir.",
  "text.the_newest_member_of_the_recovery_crew_brought_a_cc8b08": "Kurtarma ekibinin en yeni üyesi, ödünç alınan bir kask ve crayon'da çekilen bir harita getirdi. Her ikisi de şaşırtıcı derecede güvenilirydi.",
  "text.a_rescue_worker_who_once_held_a_collapsing_bridg_44755c": "Bir zamanlar geçen kurye geçinceye kadar bir çökmüş olan bir kurtarma işçisi. Ağır zırh çoğunlukla herkesin zihnini içindir.",
  "text.the_old_island_racing_champion_traded_prize_mone_a07a46": "Eski ada yarış şampiyonu bir çift deneysel çizmeler için para kazandı. scorch işaretleri şimdi kayıtlı bir imza.",
  "text.a_radio_operator_who_can_hear_the_rhythm_hiding__b613cb": "Makine sohbetinde saklanan ritmi duyan bir radyo operatörü. Her atış bir sonraki vuruşa zamanlanır.",
  "text.enemy_92b09d": "DÜŞMAN DÜŞMAN",
  "text.a_veteran_of_the_old_island_network_patched_up_a_9525a3": "Eski ada ağının bir gazisi, yukarı uzandı ve devriyeye geri gönderildi.",
