  "text.biome_05c008": "BİOME",
  "text.the_repair_crews_left_flowers_growing_between_th_c2ad6c": "Onarım ekipleri, devre tahtaları arasında büyüyen çiçekler bıraktı. Her macera parlak bir yerde başlar.",
  "text.buried_relay_towers_still_hum_beneath_the_sunset_9473fb": "Buried röle kuleleri hala gün batık kumun altında donuyor. Rüzgar şarkılarını hatırlıyor.",
  "text.the_mountain_antennae_catch_signals_from_stars_n_ca0ea0": "Dağ anteni hiç kimsenin isimlendirmediği yıldızlardan sinyalleri yakalar. Buz eski makineleri korur.",
  "text.deep_under_the_islands_the_planet_keeps_its_own__c22366": "Adaların altında, gezegen kendi fırınını çalıştırıyor. Buradaki makineler ısıyı sevmeyi öğrendi.",
