  "text.level_up_5b0ee6": "SEVİYE ATLADIN!",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "3 karttan 1 tanesini seçin (kullanınız veya anahtarlar 1-3) Alttaki kurdele, yükseltmelerin ne olduğunu söylüyor: LEFT CLICK, KCK, ÖZEL, AUTO WEAPON veya ITEM.",
  "text.evolution_fork_634218": "EVRİM YOLU",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "Evrime dönüşmek için yeterli rütbe! İki formdan birini seçin ve yeni Mods'in anahtarlayabileceği bir etiket ekler.",
  "text.the_shop_37cbe7": "DÜKKÂN",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "Mods 5 yuvada oturuyor ve hasarınızın nasıl çalıştığını değiştiriyorsunuz. Gold her aşamada net bir şekilde ilgilenmeye devam ediyorsun, bu yüzden tasarruf ödeyebilir.",
  "text.mod_order_matters_7598df": "MOD SIRALAMASI ÖNEMLİ",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "Hasar Mods LEFT aracılığıyla doğruya akışlar: (damage + ekler) x multajlar. \"+damage\" Mods daha önce \"x hasar\" olanları oklarla kopyalayın. Echo, Mod'i sağa kopyalar.",
  "text.elite_07576c": "ELİTE!",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "Bir modifier ile büyük, sert bir düşman (kahkaha, hızlı, bölme...) Onun kafatası barı hayatını gösterir.",
  "text.exposed_e6c328": "SAVUNMASIZ",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "Doğru tıklamalar Expose düşmanları: 4 s için herkesin% 30 zarar. Sağ tıklama ile açık, solla bitirmek.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "Burn ticks hasarı, Şok düşmanların% 20'sini aldığında, Freeze onları durdurur.Bir combo için aynı düşmana iki koyun.",
  "text.status_combo_f68922": "STATUS COMBO!",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "Yanma + Şok = AŞIRI YÜK patlaması. Donmuş bir düşmanı öldür = PARÇALANMA. Yanan düşmana patlamayla vur = NAPALM. Modlar her birini güçlendirebilir.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "Canı 66% ve 33% olduğunda saldırıları değişir. Kırmızı alan ve çizgiler uyarıdır: içlerinden atıl (⟪0⟫) veya mermileri savuştur (⟪1⟫).",
  "text.treasure_chest_81663c": "HAZİNE SANDIĞI",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "Yerdeki ücretsiz bir eşya için içine gir. Ekran kenar noktalarındaki ok en yakınına işaret eder.",
  "text.special_ready_f6a478": "ÖZEL HAZIR",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "Özeliniz için ⟪0⟫ (veya orta tıklama) basın. Zaman içinde yeniden şarj eder.",
  "text.ultimate_ready_d08f2b": "ULTİMATE HAZIR",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "Basın ⟪0⟫! Mükemmel dodges, parries ve kahramanınızın nihailiğini sorumluyor.",
  "text.style_meter_8e60e9": "STYLE METRE",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "Hızlı öldürme, mükemmel dodges ve parries, D'den SS. Higher stilinden stilinizi daha fazla puan ve XP'ye verir.",
  "text.gear_f7f969": "DİŞLİ",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "Her dişli bir seviye kartı (⟪0⟫ seviyesi ekrandaki).",
  "text.stage_clear_4e29fa": "BÖLÜM TAMAMLANDI",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "Sonraki bölüme geçmek için portala gir. Her bölüm daha zordur; her 4. bölümün sonunda son boss vardır.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "Bir takım arkadaşı sizi 3 s. Bu arada başka bir takım arkadaşı izlemek için geri döndürüyor.",
  "text.teammate_down_47afc6": "TAKIM ARKADAŞIN DÜŞTÜ",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "Onları yeniden canlandırmak için 3 s için bir sonraki yere otur. Her ikiniz de yenilmezlik anı elde edersiniz.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ veya sol sopa ile etrafta dolaşın. Her zaman hedef aldığınız yerde yüzleşin.",
  "text.aim_and_fire_e2180c": "AİM VE ATEŞ",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "Fare veya sağ çubukla nişan al, ⟪0⟫ ile ateş etmek için SOL TIK basılı tut. ⟪1⟫ hedef botunu yok et.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "⟪0⟫'iniz için (veya X) iletişim kurun. onun vuruşları EXPOSE düşmanları: 4 s için herkesten% 30 zarar. büyük bot.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "Basın ⟪0⟫ to dash: orta-dash. Dash THROUGH'i vurmadan önce pembe bir atışa vuramazsınız.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "Pres ⟪0⟫ (veya B) tam olarak pembe bir atış sizi atıcıya geri ulaştırır.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "Özeliniz hazır: ⟪0⟫ (veya RB) botların yanında ⟪1⟫'nizi kurmak için basın. Zaman içinde şarj eder.",
  "text.ultimate_df1d2d": "ULTİ",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "Mükemmel dodges, parries ve kahramanınızın ULTIMATE'sini öldürür. Bu tam: ⟪0⟫ (veya R3).",
